@Component("tag-handler")
@ProcessingGroup("tag-processing-group")
public class TagEventHandler {
	
	// core constructor
	TagEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateTagEvent
     */
    @EventHandler
    public void handle( CreateTagEvent event) {
        entityManager.persist(new Tag(event.getTagId(), event.getName(), event.getDatasets(), event.getModels(), event.getModelVersions(), event.getDashboards(), event.getReports(), event.getFeatureSets(), event.getMetrics(), event.getCategory()));
    }

    /*
     * @param	event UpdateTagEvent
     */
    @EventHandler
    public Tag handle( UpdateTagEvent event) {
    	entityManager.merge(new Tag(event.getTagId(), event.getName(), event.getDatasets(), event.getModels(), event.getModelVersions(), event.getDashboards(), event.getReports(), event.getFeatureSets(), event.getMetrics(), event.getCategory()));
    }
    
    /*
     * @param	event DeleteTagEvent
     */
    @EventHandler
    public void on( DeleteTagEvent event) {
    	Tag entity = new Tag();
   
    	// ------------------------------------------
    	// apply the TagId
    	// ------------------------------------------
    	entity.setTagId( event.getTagId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final TagRepository tagEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(TagEventHandler.class.getName());

}
